return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'French (France)','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 09:22+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'fr_FR','plural-forms'=>'nplurals=2; plural=n > 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" enregistré.','"%1$s" created. %2$d template updated.'=>'"%1$s" créé. %2$d modèle(s) mis à jour.' . "\0" . '"%1$s" créé. %2$d modèles mis à jour.','"%s" created.'=>'"%s" créé.','"product" (replaces "article")'=>'« produit » (remplace « article »)','%1$d chars — good length. %2$s'=>'%1$d caractères — bonne longueur. %2$s','%1$d chars — may be truncated in SERPs (aim for 140–160). %2$s'=>'%1$d caractères — peut être tronqué dans les SERPs (viser 140–160). %2$s','%1$d chars — too short (aim for 140–160). %2$s'=>'%1$d caractères — trop court (viser 140–160). %2$s','%1$d internal, %2$d external.'=>'%1$d interne, %2$d externe.','%1$d of %2$d image(s) missing alt text.'=>'%1$d image(s) sur %2$d sans texte alternatif.','%d chars — good length.'=>'%d caractères — bonne longueur.','%d external link(s), no internal links. Add internal links to related content.'=>'%d lien(s) externe(s), pas de liens internes. Ajoutez des liens internes vers du contenu lié.','%d H1 tags found — a page should have exactly one H1.'=>'%d balises H1 trouvées — une page doit avoir exactement une H1.','%d image(s), all have alt text.'=>'%d image(s), toutes avec texte alternatif.','%d language not yet linked'=>'%d langue pas encore liée' . "\0" . '%d langues pas encore liées','%d link updated.'=>'%d lien mis à jour.' . "\0" . '%d liens mis à jour.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d fichier(s) de langue n’a pas pu être supprimé(s) automatiquement (DISALLOW_FILE_MODS est activé). Supprimez-le(s) manuellement via votre serveur ou WP-CLI : wp language core uninstall <locale>.' . "\0" . '%d fichiers de langue n’ont pas pu être supprimés automatiquement (DISALLOW_FILE_MODS est activé). Supprimez-les manuellement via votre serveur ou WP-CLI : wp language core uninstall <locale>.','%d locale file removed.'=>'%d fichier(s) de langue supprimé(s).' . "\0" . '%d fichiers de langue supprimés.','%d locale pack installed.'=>'%d pack de localisation installé.' . "\0" . '%d packs de localisation installés.','%d navigation reference updated.'=>'%d référence de navigation mise à jour.' . "\0" . '%d références de navigation mises à jour.','%d part reference updated.'=>'%d référence de partie mise à jour.' . "\0" . '%d références de partie mises à jour.','%d words — below recommended minimum of 300.'=>'%d mots — en dessous du minimum recommandé de 300.','%d words — very thin content. Consider expanding to at least 300 words.'=>'%d mots — contenu très mince. Envisagez d’étendre à au moins 300 mots.','%d words.'=>'%d mots.','%s Archive'=>'Archive %s','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s est actif et génère déjà du JSON-LD Schema.org. Lingua Forge a désactivé sa propre sortie de schéma pour éviter les conflits. Contrairement à Open Graph — où LF ajoute og:locale en plus de la sortie d’un autre plugin — le schéma ne peut pas être complété proprement : des graphes JSON-LD en double ou en chevauchement produisent des erreurs de validation. Désactivez la sortie de schéma dans le plugin détecté si vous souhaitez que LF gère les données structurées.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s est actif et génère son propre sitemap. Ce sitemap est séparé de celui de LF. Les deux doivent être soumis à Google Search Console : le sitemap du plugin SEO liste votre contenu ; le sitemap de LF ajoute les liens alternatifs multilingues. Le sitemap de LF est annoncé dans robots.txt automatiquement.','(avg %.1f hits/block)'=>'(moy. %.1f hits/bloc)','(avg %.1f hits/entry)'=>'(moy %.1f coups/entrée)','(disabled)'=>'(désactivé)','(no title) #%d'=>'(pas de titre) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} n\'avait pas de liens à remplacer — ré-analyse pour investiguer)','.txt file(s) in the directory'=>'.txt fichier(s) dans le répertoire','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — aucune sous-titre H2 trouvé. Ajouter des H2 améliore la structure.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge :</strong> %1$d modèle(s) localisé(s) du thème « %2$s » sont conservés dans la base de données mais sont actuellement inactifs. Ils redeviendront actifs si vous réactivez ce thème. Pour transférer vos traductions vers le nouveau thème, régénérez-les via <strong>Paramètres → Lingua Forge → Routage → Gabarit FSE</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> lien(s) automatiquement corrigeable(s)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> lien(s) nécessitant une révision manuelle','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> chemin(s) obsolète(s)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problème(s) de modèle','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Un fichier robots.txt physique existe à la racine du site. Le robots.txt virtuel de WordPress — et le filtre Sitemap de LF — sont contournés. Le sitemap de LF n’est pas annoncé aux moteurs de recherche.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'N\'accepte que les fichiers .mo compilés. Le nom de fichier doit suivre le modèle {textdomain}-{locale}.mo. Le téléchargement d\'un fichier portant le même nom qu\'un existant le remplacera.','Action'=>'Action','Actions'=>'Actions','active'=>'actif','Active Languages'=>'Langues actives','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Langues actives : ajoutez chaque langue que vous souhaitez prendre en charge. Chaque langue obtient un préfixe d\'URL ou un sous-domaine et une balise hreflang dans la section &lt;head&gt; de la page.','Active Provider'=>'Fournisseur actif','Add entry'=>'Ajouter une entrée','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Ajouter des instructions pour améliorer le brouillon — par exemple, le rendre plus court, ajouter une section de conclusion, utiliser un registre plus formel, inclure un bloc FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Ajoutez des instructions pour améliorer le brouillon — par exemple, le rendre plus court, ajouter une conclusion, utiliser un registre plus formel…','Add new entry'=>'Ajouter une nouvelle entrée','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Ajoutez un terme par ligne. La terminologie source et la traduction cible sont toutes deux requises. La paire de langues détermine à quels travaux de traduction la contrainte s\'applique.','Add Sitemap directive to robots.txt'=>'Ajouter la directive Sitemap à robots.txt','Add the following line to your robots.txt manually:'=>'Ajoutez la ligne suivante à votre robots.txt manuellement :','Add WooCommerce product tags to Open Graph output'=>'Ajouter les tags de produits WooCommerce à la sortie Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Ajoute un lien vers la page d\'accueil pour que les visiteurs puissent naviguer dans leur langue.','Administrators only (manage_options)'=>'Administrateurs uniquement (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Après avoir changé la langue principale, videz les permaliens (section ci-dessous) pour que la redirection URL soit mise à jour.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Après avoir modifié les paramètres de la structure des URL (préfixe de chemin ↔ sous-domaine), visitez toujours Paramètres → Permaliens et cliquez sur Enregistrer les modifications pour vider les règles de réécriture.','AI analysis failed. Please try again.'=>'Échec de l’analyse par l’IA. Veuillez réessayer.','AI Behaviour Preset'=>'Préréglage de comportement AI','AI cache cleared. %d entry was removed.'=>'Cache IA vidé. %d entrée(s) ont été supprimée(s).' . "\0" . 'Cache IA vidé. %d entrées ont été supprimées.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Cache AI : liste les réponses AI mises en cache avec le nombre de hits. Effacez tout le cache ou les entrées d\'un seul article. Utilisez "Effacer" avant de tester un changement de traduction — les résultats en cache sont renvoyés même lorsque vous modifiez le préréglage ou le modèle AI jusqu\'à ce que l\'entrée du cache soit évincée.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Les fonctionnalités AI sont optionnelles. Le routage linguistique, hreflang, le sélecteur de langue et le système de groupe de traduction fonctionnent tous sans fournisseur configuré.','AI Limits & Security'=>'Limites et sécurité de l\'IA','AI provider returned an empty response.'=>'Le fournisseur d\'IA a renvoyé une réponse vide.','AI Recommendations'=>'Recommandations IA','AI returned an unexpected response format. Please try again.'=>'L’IA a renvoyé un format de réponse inattendu. Veuillez réessayer.','AI Usage'=>'Utilisation de l\'IA','AI Usage & Cache'=>'Utilisation & Cache de l’IA','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Visez 120–160 caractères. Laissez vide pour utiliser le fallback de l\'extrait.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Tous les principaux moteurs de recherche — Google, Bing et Yandex — découvrent automatiquement le sitemap via la directive Sitemap : dans robots.txt. Aucune action manuelle n’est requise. Les boutons ci-dessous envoient une requête immédiate pour que le moteur recrawle le sitemap maintenant plutôt que d’attendre sa prochaine vérification programmée de robots.txt.','All time'=>'Tout le temps','All types'=>'Tous les types','Allow editors to lock individual blocks'=>'Permettre aux éditeurs de verrouiller des blocs individuels','Allow Gutenberg template-editing mode on post screens'=>'Permettre le mode d\'édition de modèle Gutenberg sur les écrans de publication','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Supprimer également les affectations de langue, les relations de traduction, les méta-descriptions, le glossaire et la mémoire de traduction lors de la désinstallation du plugin.','Also generate meta description'=>'Générer également une méta description','Alternative (server-side):'=>'Alternatif (côté serveur) :','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Émettre toujours uniquement og:locale et og:locale:alternate. À utiliser lorsque un autre plugin ou thème gère l’ensemble OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Émettre toujours l’ensemble complet OG + Twitter Card, indépendamment des autres plugins. À utiliser uniquement si aucun autre plugin ne génère des balises OG.','An unknown error occurred.'=>'Une erreur inconnue est survenue.','Analysis'=>'Analyse','Analysis request failed. Please try again.'=>'Échec de la demande d’analyse. Veuillez réessayer.','Analyze'=>'Analyser','Analyzing…'=>'Analyse en cours…','and'=>'et','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'n\'importe','API calls saved by cache'=>'Appels API sauvegardés par cache','API Key'=>'Clé API','API Keys'=>'Clés API','API Keys Tab'=>'Onglet Clés API','API Response Cache'=>'Cache de réponse API','Appends the following line to your existing robots.txt: %s'=>'Ajoute la ligne suivante à votre robots.txt existant : %s','Applied ✓'=>'Appliqué ✓','Apply failed — please try again.'=>'L\'application a échoué — veuillez réessayer.','Apply to Block'=>'Appliquer au bloc','Apply to Editor'=>'Appliquer à l\'éditeur','Apply to Footnote'=>'Appliquer à la note de bas de page','Apply to Meta Description'=>'Appliquer à la méta description','Apply translation'=>'Appliquer la traduction','Applying…'=>'Application en cours…','Approximate size'=>'Taille approximative','Archive'=>'Archive','Archive: %s'=>'Archive : %s','Article / WebPage'=>'Article / Page Web','Article / WebPage — all singular posts and pages'=>'Article / Page Web — toutes les publications et pages singulières','Authors and above (edit_published_posts)'=>'Auteurs et plus (edit_published_posts)','Auto (recommended)'=>'Auto (recommandé)','Behavior'=>'Comportement','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportement : choisissez le préréglage AI (Littéral, Équilibré, Créatif), ajoutez des instructions de prompt personnalisées à l\'échelle du site, activez ou désactivez la traduction automatique après sauvegarde de l\'article, et configurez la Mémoire de traduction.','Block Content'=>'Contenu du bloc','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Affiche un avis poli lorsque la page actuelle est affichée dans sa langue source parce qu\'aucune traduction n\'existe dans la langue du visiteur. Piloté par le signal LINGUAFORGE_LANG_FALLBACK_ACTIVE du routeur Lingua Forge — ne produit rien lorsqu\'une traduction existe pour la locale demandée.','Block Editor'=>'Éditeur de blocs','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'langue','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'traduction','Block locking'=>'Verrouillage de bloc','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Modèles enregistrés pour les types de publication personnalisés. Utilisez le bouton Traduire pour produire une variante linguistique. Le contenu traduit est enregistré ici et peut être copié dans n\'importe quel article CPT depuis l\'inserteur de modèles du bloc ou utilisé comme point de départ pour un Modèle synchronisé (Bloc réutilisable).','block titleMissing Translation Notice'=>'Avis de traduction manquante','Block translation reuses'=>'Réutilisations de traduction de blocs','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Cache de traduction au niveau du bloc partagé entre les articles. Lorsqu\'il est activé, les blocs identiques (même balisage, paire de langues et glossaire) sont servis depuis la mémoire au lieu d\'appeler à nouveau l\'IA. Configurez dans Paramètres → Comportement.','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Les articles de blog utilisent Article ; tous les autres types de publication et pages utilisent WebPage. Inclut titre, description, inLanguage, url, datePublished, dateModified, image, et éditeur.','Browser language redirect'=>'Redirection par langue du navigateur','Built-in preset instructions:'=>'Instructions prédéfinies intégrées :','Bulletize (•-prefixed)'=>'Présenter sous forme de puces (préfixé par •)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Met en cache les équivalents traduits au niveau du bloc pour que le contenu réutilisable (pieds de page partagés, barres latérales, accordéons, sections juridiques lourdes en boilerplate) ne paie pas un appel API à chaque fois. Lorsqu\'il est activé, le flux de traduction analyse chaque publication en blocs, recherche chaque bloc dans le cache, et n\'envoie que les blocs non mis en cache à l\'IA dans une requête groupée. Les modifications du glossaire et les changements de préréglage de conformité invalident automatiquement les traductions mises en cache affectées. Voir les statistiques et effacer le cache sous Maintenance.','cached'=>'en cache','Cached API responses'=>'Réponses API en cache','Cached block translations'=>'Traductions de blocs en cache','Cancel'=>'Annuler','Cannot determine target language from slug.'=>'Impossible de déterminer la langue cible à partir du slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Impossible d’écrire sur le produit %1$d : c’est une version traduite (langue : %2$s)%3$s. Les données opérationnelles (prix, stock, SKU, dimensions) doivent être mises à jour sur le produit source. Résolvez l’ID du produit source via : GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Balise canonique','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limiter l\'utilisation de l\'IA que le site peut générer et restreindre quels rôles d\'utilisateur peuvent déclencher des appels payants à l\'IA. Se superpose à la limite de taux par utilisateur (30 requêtes / minute, codée en dur) qui protège déjà contre les boucles incontrôlées d\'un seul utilisateur.','chars'=>'caractères','Chunk translated'=>'Segment traduit','Chunk translated to:'=>'Segment traduit en :','Clear'=>'Effacer','Clear All'=>'Tout effacer','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Vider tous les résultats en cache de l\'IA ? Les requêtes futures déclencheront des appels API frais jusqu\'à ce que le cache soit reconstruit.','Clear API Response Cache'=>'Vider le cache de réponse API','Clear Debug Files'=>'Vider les fichiers de débogage','Clear hints'=>'Effacer les indices','Clear input'=>'Effacer l\'entrée','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Vider toute la mémoire de traduction ? Les traductions futures reconstruiront le cache à leur exécution.','Clear Translation Memory'=>'Vider la mémoire de traduction','Close'=>'Fermer','Close language panel'=>'Fermer le panneau de langue','Close popover'=>'Fermer l\'infobulle','Compatibility'=>'Compatibilité','Compliance Preset'=>'Préréglage de conformité','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configurez un fournisseur d’IA dans Paramètres → Clés API pour activer les recommandations alimentées par l’IA.','Content generated'=>'Contenu généré','Content Generator'=>'Générateur de contenu','Content ready'=>'Contenu prêt','Contributors and above — default (edit_posts)'=>'Contributeurs et plus — par défaut (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Contrôler la quantité de contenu envoyée à l\'IA et la taille maximale de la réponse. Laissez un champ vide pour utiliser la valeur par défaut intégrée (affichée en tant que placeholder). Augmentez ces valeurs si de grandes pages sont coupées ; réduisez-les pour diminuer les coûts API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Contrôle le budget de jetons et les limites d\'entrée pour la fonction Générateur de contenu IA. Laissez les champs vides pour utiliser les valeurs par défaut intégrées.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Contrôle ce qui se passe lorsqu\'un administrateur supprime le plugin dans Plugins → Plugins installés → Supprimer. Les paramètres du plugin et les caches AI sont toujours supprimés. Les affectations de langue et les relations de traduction sont conservées par défaut pour que la désinstallation accidentelle ou la réinstallation puissent reprendre là où elles s\'étaient arrêtées.','Conversational'=>'Conversationnel','Copied ✓'=>'Copié ✓','Copy'=>'Copier','Copy failed — please copy the URL manually.'=>'La copie a échoué — veuillez copier l’URL manuellement.','Copy markup'=>'Copier le code','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Copiez l’URL actuelle dans le presse-papiers. Affiche un toast « Lien copié » en cas de succès.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Copiez le résultat et collez-le où vous en avez besoin (par exemple, directement dans le champ de la note de bas de page).','Copy to safe storage'=>'Copier dans le stockage sécurisé','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'actions JS natives/copies/auto : gérées par LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'Impossible d\'ajouter l\'entrée : le terme source et le terme cible sont obligatoires.','Could not copy the file. Check that the uploads folder is writable.'=>'Impossible de copier le fichier. Vérifiez que le dossier uploads est accessible en écriture.','Could not instantiate the provider.'=>'Impossible d\'instancier le fournisseur.','Could not save the file. Check that the uploads folder is writable.'=>'Impossible d\'enregistrer le fichier. Vérifiez que le dossier uploads est accessible en écriture.','Could not save the glossary entry.'=>'Impossible d\'enregistrer l\'entrée du glossaire.','Could not write to robots.txt. Check file permissions.'=>'Impossible d\'écrire dans robots.txt. Vérifiez les permissions du fichier.','CPT Block Patterns'=>'Modèles de blocs CPT','Create'=>'Créer','Create missing'=>'Créer manquant','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'La création de traductions pour le type de publication "%s" nécessite une intégration active. Veuillez vous assurer que l\'intégration requise est installée et active.','Creating…'=>'Création…','Creative / Marketing'=>'Créatif / Marketing','Creative / Marketing instructions'=>'Instructions créatives / marketing','Current content (will be overwritten)'=>'Contenu actuel (sera écrasé)','Current status'=>'Statut actuel','Current title'=>'Titre actuel','Current: {current}'=>'Actuel : {current}','Currently emitting'=>'Actuellement émis','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actuellement hérité de la constante %s. La sélection d\'une valeur ici la remplacera.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actuellement ignoré pour les publications utilisant des espaces réservés d\'attributs de commentaire de bloc (champs wp:details, etc.) — ils passent par le chemin de traduction à appel unique existant.','Currently:'=>'Actuellement :','Custom'=>'Personnalisé','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Quota quotidien d\'IA atteint (%1$d demandes). Réinitialise à %2$s UTC.','Daily request limit'=>'Limite de requêtes quotidienne','Danger Zone'=>'Zone de danger','Debug Files'=>'Fichiers de débogage','Debug files cleared. %d file was removed.'=>'Fichiers de débogage supprimés. %d fichier a été supprimé.' . "\0" . 'Fichiers de débogage supprimés. %d fichiers ont été supprimés.','Debug logging'=>'Journalisation de débogage','Debug logging disabled.'=>'Journalisation de débogage désactivée.','Debug logging enabled.'=>'Journalisation de débogage activée.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Débogage : activez le journal de débogage pour capturer les prompts AI et les réponses API dans un fichier local. Désactivez après dépannage — le mode débogage écrit un fichier à chaque requête AI.','Default OG image'=>'Image OG par défaut','Delete'=>'Supprimer','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Supprimer tous les fichiers .txt dans le répertoire de débogage ? Le répertoire lui-même restera en place pour que les futurs écrits de débogage soient enregistrés proprement.','Delete all files for this override (both .mo and .po)?'=>'Supprimer tous les fichiers pour cette surcharge (les fichiers .mo et .po) ?','Delete content data on uninstall'=>'Supprimer les données de contenu lors de la désinstallation','Delete this glossary entry?'=>'Supprimer cette entrée du glossaire ?','Describe what to write — topic, key points, structure…'=>'Décrivez ce que vous souhaitez écrire — sujet, points clés, structure…','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Détecter les plugins SEO actifs (Yoast, Rank Math, etc.) lors de l\'exécution. Émettre uniquement og:locale + og:locale:alternate lorsqu\'un autre plugin fournit déjà l\'ensemble complet OG ; émettre l\'ensemble complet lorsqu\'aucun n\'est détecté.','Directory'=>'Répertoire','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Désactiver lors de l\'ajustement du prompt ou lorsque vous avez besoin que chaque requête atteigne le fournisseur AI. La désactivation ne supprime pas les entrées en cache — leur réactivation les restaure. Il est attendu d\'augmenter immédiatement les dépenses API sur les sites occupés lorsqu\'il est désactivé.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Désactiver uniquement pour les sites sans tête ou les implémentations hreflang entièrement personnalisées. Lorsqu\'il est désactivé, LF ne supprime plus la balise canonique de WordPress et ne supprime plus la sortie hreflang du plugin SEO.','Disabled'=>'Désactivé','Disabled (by setting)'=>'Désactivé (par paramètre)','Disabled (mode setting)'=>'Désactivé (mode paramètre)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Désactivé car le mu-plugin lf-social-share fournit déjà cette fonctionnalité.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS est activé.','Display'=>'Affichage','Displays the Lingua Forge language switcher.'=>'Affiche le sélecteur de langue de Lingua Forge.','Do not output any OG tags.'=>'Ne pas générer de balises OG.','Documentation'=>'Documentation','Done'=>'Terminé','Done — {done} of {total} post(s) fixed.'=>'Terminé — {done} sur {total} articles corrigés.','Down'=>'Bas','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Téléchargez et installez un pack linguistique du noyau WordPress directement depuis WordPress.org. Une fois installé, la localisation devient disponible pour le routage URL et le flux de traduction AI. La liste des langues disponibles est récupérée à la demande — cliquez sur le bouton ci-dessous pour la charger.','Dropdown direction'=>'Direction du menu déroulant','edit'=>'modifier','Editors and above (edit_others_posts)'=>'Éditeurs et plus (edit_others_posts)','Enable API response caching'=>'Activer la mise en cache des réponses API','Enable block-level translation cache reuse across posts'=>'Réutilisation du cache de traduction au niveau des blocs à travers les publications','Enable Social Share URL rewriting for Social Icons blocks'=>'Activer la réécriture des URL de partage social pour les blocs d\'icônes sociales','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Entrez votre clé API pour au moins un fournisseur AI. Les clés sont chiffrées au repos à l\'aide de AES-256-GCM avec un secret spécifique au site (LINGUAFORGE_SECRET). Ne partagez pas les exports de base de données sans faire d\'abord une rotation du secret.','environment variable'=>'variable d\'environnement','Error'=>'Erreur','Expand'=>'Développer','Expected: {expected}'=>'Attendu : {expected}','External share services'=>'Services de partage externes','Extra guidance — tone, style, constraints, target audience…'=>'Conseils supplémentaires — ton, style, contraintes, public cible…','Extra guidance — tone, style, constraints…'=>'Conseils supplémentaires — ton, style, contraintes…','Failed. Please try again.'=>'Échec. Veuillez réessayer.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL d\'image de secours utilisée lorsqu\'une page n\'a pas d\'image mise en avant, de logo du site ou d\'icône du site. Affichée dans les aperçus sociaux pour les archives, l\'index du blog et toute page singulière sans vignette.','Feature'=>'Fonctionnalité','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Les fonctionnalités sont regroupées en deux niveaux. Entrez l\'identifiant exact du modèle pour chaque niveau et fournisseur. Laissez un champ vide pour utiliser la valeur par défaut intégrée (affichée en tant que placeholder). Seuls les modèles du fournisseur actif sont appelés en temps réel — configurez les autres à l\'avance si vous prévoyez de changer.','File copied to safe storage successfully.'=>'Fichier copié dans le stockage sécurisé avec succès.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Les modifications de fichiers sont désactivées (DISALLOW_FILE_MODS).','Files'=>'Fichiers','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Les fichiers sont enregistrés dans le répertoire ci-dessous. Utile pour diagnostiquer les problèmes de traduction — désactivez une fois que vous avez ce dont vous avez besoin pour éviter l\'accumulation de fichiers. Vous pouvez également forcer cela depuis wp-config.php avec `define( \'LINGUAFORGE_AI_DEBUG\', true );` qui override ce bouton.','Filter'=>'Filtrer','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtrer par langue et type de publication, parcourir votre contenu, et cliquer sur Analyser sur n\'importe quel élément pour lancer un audit SEO basé sur des règles — longueur du titre, méta description, nombre de mots, structure des titres, couverture des attributs alt des images, et liens internes.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtrer avec linguaforge_debug_dir pour rediriger la sortie de débogage vers un emplacement non public.','Finding'=>'Recherche','Fix'=>'Corriger','Fix All'=>'Tout corriger','Fix all links'=>'Corriger tous les liens','Fix all parts'=>'Corriger toutes les parties','Fix Links'=>'Corriger les liens','Fix Nav'=>'Corriger la navigation','Fix Parts'=>'Corriger les parties','Fix Template'=>'Corriger le modèle','Fixing {n} / {total}…'=>'Correction de {n} / {total}…','Fixing…'=>'Correction en cours…','Flush Permalink Rules'=>'Vider les règles de permalien','Flush Permalinks'=>'Vider les permaliens','Flush Sitemap Cache'=>'Vider le cache du sitemap','Footnote Content'=>'Contenu de la note de bas de page','footnote(s) translated — applied together with content.'=>'note(s) de bas de page traduite(s) — appliquée(s) avec le contenu.','Footnotes'=>'Notes de bas de page','Footnotes payload (advanced)'=>'Charge utile des notes de bas de page (avancé)','Forbidden'=>'Interdit','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forcé DÉSACTIVÉ par la constante LINGUAFORGE_AI_DEBUG dans wp-config.php. Supprimez cette ligne pour contrôler ce bouton ici.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forcé ACTIVÉ par la constante LINGUAFORGE_AI_DEBUG dans wp-config.php. Supprimez cette ligne pour contrôler ce bouton ici.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Force la régénération du sitemap lors de la prochaine requête. À utiliser après une importation en masse ou une modification manuelle des relations de traduction.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Trouvé {parts} sur <strong>{total}</strong> des <strong>{scanned}</strong> articles analysés pour <strong>{lang}</strong>.','From'=>'De','Front Page'=>'Page d\'accueil','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localisation FSE : créez, traduisez et corrigez les liens dans les modèles et parties de modèles Full Site Editing directement depuis cet onglet.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Modèles FSE issus du thème actif. Créez puis personnalisez dans l\'éditeur de site.','Full'=>'Complet','Full Article'=>'Article complet','Full post'=>'Article complet','General'=>'Général','Generate'=>'Générer','Generate Content'=>'Générer du contenu','Generate content…'=>'Générer du contenu…','Generate Excerpt'=>'Générer un extrait','Generate Meta Description'=>'Générer une méta description','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Générer le sitemap multilingue à /lf-sitemap.xml','Generated Content'=>'Contenu généré','Generated meta description'=>'Meta description générée','Generating…'=>'Génération en cours…','Generation failed.'=>'Échec de la génération.','Getting started'=>'Commencer','Global AI preset'=>'Préréglage IA global','Global default (%s)'=>'Par défaut global (%s)','Glossary'=>'Glossaire','Glossary entry added.'=>'Entrée du glossaire ajoutée.','Glossary entry removed.'=>'Entrée du glossaire supprimée.','Glossary Tab'=>'Onglet Glossaire','Google (Gemini)'=>'Google (Gemini)','Headings'=>'Titres','Hide'=>'Cacher','Hints'=>'Indices','Home link text'=>'Texte du lien vers la page d\'accueil','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Comment elle doit apparaître dans la traduction. Tapez la même valeur que le terme source pour demander à l\'IA de la préserver tel quel.','How to use'=>'Comment utiliser','Hreflang'=>'Hreflang','Hreflang output'=>'Sortie hreflang','Hreflang settings saved.'=>'Paramètres hreflang enregistrés.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Icone + étiquette','Icon only'=>'Icone uniquement','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si cette option est cochée, la désinstallation du plugin supprimera définitivement toutes les affectations de langue, relations de traduction, méta-descriptions, préréglages par page, le glossaire AI et la mémoire de traduction pour chaque article de ce site. Cela ne peut pas être annulé. Laissez-la décochée sauf si vous supprimez complètement le support multilingue du site.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Si vous avez installé un plugin SEO général, ce panneau montre comment LF s\'adapte pour éviter la sortie en double. L\'objectif est d\'éviter les collisions — pas la coopération. LF fournit toujours la couche SEO multilingue (hreflang, og:locale, schéma inLanguage) qui nécessite la connaissance de la configuration de routage linguistique de LF pour produire correctement.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Si vous avez installé Yoast SEO, Rank Math, All in One SEO, ou SEOPress, Lingua Forge les détecte et s\'adapte pour éviter la sortie en double. Pour hreflang, LF prend le contrôle total et supprime la sortie du plugin car ces plugins ne peuvent pas produire un hreflang correct pour une configuration de routage multilingue. Pour Open Graph, LF ajoute uniquement og:locale et og:locale:alternate — les signaux multilingues que le plugin ne peut pas fournir — et laisse l\'ensemble OG de base au plugin. Pour Schema.org, LF désactive sa propre sortie pour éviter les graphes JSON-LD conflictuels.','Images'=>'Images','Improve writing'=>'Améliorer la rédaction','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Dans l\'éditeur de blocs, ajoutez un bloc d\'icônes sociales. Pour chaque icône, ouvrez les paramètres du lien et entrez l\'une des valeurs "share:" ci-dessous comme URL. Sur le frontend, LF la remplace par la bonne URL de partage pour la page en cours.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Inclut le nom, la description, inLanguage, url, image, et une offre avec prix, devise du prix, et disponibilité. Le prix et la disponibilité proviennent du produit dans la langue source (modèle de stock partagé).','Includes site name, url, and inLanguage.'=>'Inclut le nom du site, l\'URL, et inLanguage.','Informative'=>'Informative','Input tokens'=>'Tokens d\'entrée','Install'=>'Installer','Install a Language'=>'Installer une langue','Installed SEO plugins'=>'Plugins SEO installés','Installing…'=>'Installation…','instock / oos / pending from WC stock status'=>'En stock / en rupture / en attente selon le statut de stock WC','Instructions (optional)'=>'Instructions (optionnel)','Instructions / key points'=>'Instructions / points clés','Integration API'=>'API d\'intégration','Internal Link Fixer'=>'Correcteur de liens internes','Introduction only'=>'Introduction uniquement','Invalid file reference.'=>'Référence de fichier invalide.','Invalid filename.'=>'Nom de fichier invalide.','Invalid language code.'=>'Code de langue invalide.','Invalid language.'=>'Langue invalide.','Invalid locale code.'=>'Code de localisation invalide.','Invalid or primary language.'=>'Langue invalide ou principale.','Invalid post ID.'=>'ID de publication invalide.','Invalid post type.'=>'Type de publication invalide.','Invalid template part.'=>'Partie de modèle invalide.','Invalid template type.'=>'Type de modèle invalide.','JavaScript-powered actions'=>'Actions alimentées par JavaScript','Key points, ideas, or structure to build from…'=>'Points clés, idées ou structure à partir de laquelle construire…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Les clés sont cryptées avec AES-256-CBC avant d\'être stockées dans la base de données WordPress. Le secret de cryptage est dérivé de vos sels d\'authentification WordPress (wp-config.php), donc les clés en texte clair ne touchent jamais la base de données.','Language'=>'Langue','Language %s installed successfully.'=>'La langue %s a été installée avec succès.','Language (optional)'=>'Langue (optionnel)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'L\'installation de la langue est désactivée sur ce serveur (DISALLOW_FILE_MODS est activé).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'L\'installation de la langue est désactivée sur ce serveur. La constante DISALLOW_FILE_MODS est définie dans wp-config.php. Installez manuellement les packs linguistiques via WP-CLI : wp language core install de_DE','Language label'=>'Étiquette de la langue','Language Overrides'=>'Remplacements de langue','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Surcharges de langue : gérez les fichiers de surcharge .po/.mo personnalisés pour les chaînes UI de Lingua Forge. Utilisez ceci au lieu de modifier directement les fichiers du plugin — les surcharges survivent aux mises à jour.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'L\'installation du pack linguistique a échoué. La langue est peut-être déjà installée, le code de localisation est peut-être incorrect, ou votre serveur peut bloquer l\'écriture de fichiers.','Language Setup'=>'Configuration de la langue','Language Switcher'=>'Sélecteur de langue','Language switcher'=>'Sélecteur de langue','Language uninstalled. %d post deleted.'=>'Langue désinstallée. %d publication supprimée.' . "\0" . 'Langue désinstallée. %d publications supprimées.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Copies spécifiques à la langue des parties de modèles du thème. Une fois créés, les modèles sont mis à jour pour faire référence à la partie spécifique à la langue.','Language:'=>'Langue :','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Langues actuellement connues du routeur (dérivées des packs de localisation WordPress installés plus la langue principale). Installez des packs linguistiques supplémentaires dans la section ci-dessous pour rendre plus de langues disponibles pour le routage et la traduction.','Last 30 days'=>'Derniers 30 jours','Last 7 days'=>'Derniers 7 jours','Last generated: %s'=>'Dernière génération : %s','Lead paragraph (≤60 w)'=>'Paragraphe d\'introduction (≤60 mots)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Laissez un champ de modèle vide pour utiliser le paramètre par défaut intégré pour ce niveau. Le texte de l\'espace réservé indique quel modèle sera utilisé.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Laissez vide pour les noms de marques et les termes indépendants de la langue qui doivent être appliqués quelle que soit la langue de traduction.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Laissez vide pour appliquer cette entrée à toutes les langues cibles — idéal pour les noms de marques, abréviations, et termes qui doivent être conservés tel quel dans chaque traduction.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Laissez vide pour conserver la clé existante. Entrez une nouvelle valeur pour la remplacer.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Laissez vide pour utiliser la valeur par défaut intégrée. Effacer une override enregistrée restaure la valeur par défaut lors du prochain enregistrement.','Legacy lf-social-share mu-plugin'=>'Ancien mu-plugin lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Mu-plugin lf-social-share détecté. LF reporte l\'ensemble OG de base au mu-plugin et ne sort que og:locale + og:locale:alternate. Vous pouvez désactiver le mu-plugin — LF\'s Social Share intégré (onglet SEO → Partage social) et Open Graph couvrent la même fonctionnalité.','Legal / Compliance'=>'Légal / Conformité','Legal / Compliance instructions'=>'Instructions légales / conformité','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF ajoute toujours og:locale et og:locale:alternate — les signaux OG multilingues qu\'aucun plugin SEO ne peut produire correctement. Pour l\'ensemble OG de base (og:title, og:description, og:image), LF le sort lorsque aucun autre plugin n\'est présent. Lorsqu\'un plugin SEO est installé, LF saute l\'ensemble de base pour éviter les balises en double — pas parce que le plugin est "meilleur", mais parce que la duplication ne produit aucune valeur.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF génère son propre sitemap avec des alternances xhtml:link pour tous les groupes de traduction. Lorsqu\'un plugin SEO est installé, il génère un sitemap séparé — les deux coexistent indépendamment. Soumettez les deux à Google Search Console : le sitemap du plugin SEO pour la découverte de contenu, le sitemap de LF pour les signaux de relation linguistique.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF affiche des balises hreflang et a supprimé la balise canonique du cœur de WordPress sur les pages multilingues.','LF is suppressing hreflang output from: %s'=>'LF supprime la sortie hreflang de : %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF fournit un hreflang précis pour chaque langue configurée, y compris x-default. Les plugins SEO généraux n\'ont pas accès à votre configuration de routage LF et produiraient des hreflang basés sur des suppositions d\'URL incorrectes. LF supprime leur sortie via un filtre pour éviter les collisions.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF produit du JSON-LD multilingue avec des annotations inLanguage liées à sa configuration de routage linguistique. Lorsqu\'un plugin SEO est installé, LF désactive entièrement son propre schéma : des graphes JSON-LD en double génèrent des erreurs de validation et il n\'existe pas de moyen simple de compléter un graphe existant.','LF provides'=>'LF fournit','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF supprime la balise canonique du cœur de WordPress sur les pages multilingues car les règles de réécriture avec préfixe de langue du routeur et le hreflang x-default sont les signaux canoniques corrects pour un site multilingue. Cela évite une double-canonisation si un plugin SEO en produit également une. LF n\'ajoute pas sa propre canonique — la routage linguistique rend déjà chaque URL canonique.','Light'=>'Léger','Light (default — fast and cost-effective)'=>'Léger (par défaut — rapide et économique)','Light (fast and cost-effective — Haiku / Flash)'=>'Léger (rapide et économique — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Léger : utilisé pour les descriptions meta et la génération d\'extraits — rapide, à faible coût.','Limit results to pages in the given Lingua Forge language code.'=>'Limiter les résultats aux pages dans le code de langue de Lingua Forge donné.','Limits'=>'Limites','Lingua Forge'=>'Forge de Lingua','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge ajoute un routage multilingue, une traduction alimentée par AI, des balises hreflang SEO et un sélecteur de langue à votre site WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge ajoute des propriétés Open Graph spécifiques à WooCommerce sur les pages produits afin que le partage d\'une URL de produit sur Facebook, Pinterest et autres plateformes affiche le bon type de produit, prix et disponibilité.','Lingua Forge AI Tools'=>'Outils IA de Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge étend le bloc d\'icônes sociales de WordPress Core avec des URLs de partage dynamiques. Configurez le lien de n\'importe quelle icône avec une valeur "share:" et LF le réécrit en l\'URL de partage correcte ou en action JavaScript lors du rendu — pas besoin de code personnalisé ni de plugin tiers.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge génère un sitemap XML dédié à /lf-sitemap.xml qui ajoute des liens alternatifs de langue pour tout votre contenu traduit. Ce sitemap complète le sitemap du cœur de WordPress et tout sitemap de plugin SEO — il ne les remplace pas.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge est une solution SEO multilingue complète. Aucun plugin SEO supplémentaire n\'est requis.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge est une solution SEO multilingue complète. Aucun plugin SEO ou sitemap supplémentaire n\'est requis.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge génère des balises <link rel="alternate" hreflang> pour chaque langue configurée sur chaque page, y compris x-default pointant vers la langue source. Il s\'agit du principal signal SEO multilingue pour Google et d\'autres moteurs de recherche — aucun plugin SEO supplémentaire n\'est requis.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge produit des balises meta Open Graph et Twitter Card pour que les URLs partagées affichent la bonne langue, titre, description et image sur les plateformes sociales.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge produit des données structurées JSON-LD Schema.org pour que les moteurs de recherche comprennent votre type de contenu, langue et métadonnées. C\'est la principale façon de communiquer les annotations inLanguage pour le contenu multilingue à Google et autres crawlers.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge limite par défaut deux fonctionnalités de Gutenberg pour maintenir une cohérence éditoriale entre les langues. Activez ici si vous avez besoin de toutes les capacités de Gutenberg / FSE.','Lingua Forge Settings'=>'Paramètres Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge utilise deux couches de cache indépendantes pour éviter les appels API AI redondants. Utilisez les onglets ci-dessous pour inspecter et gérer chacune.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge utilise deux niveaux de modèles par fournisseur :','Lingua Forge — Quick Translate'=>'Forge de Lingua — Traduction rapide','Lingua Forge — Settings'=>'Lingua Forge — Paramètres','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Les modules intégrés de partage social et Open Graph de Lingua Forge couvrent toutes les fonctionnalités que fournit le mu-plugin, plus la prise en charge multilingue de og:locale. Vous pouvez désactiver en toute sécurité le mu-plugin.','Link copied'=>'Lien copié','link(s)'=>'lien(s)','Links'=>'Liens','Load available languages'=>'Charger les langues disponibles','Load content'=>'Charger le contenu','Loading…'=>'Chargement…','Locale only'=>'Uniquement la locale','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Verrouillé — un plugin SEO en conflit est actif. Voir l\'avis ci-dessus.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate stocke ses traductions personnalisées dans wp-content/languages/loco/ — un emplacement qui peut être effacé silencieusement lors d\'une mise à jour du cœur WP, d\'une réinstallation du plugin ou si Loco Translate lui-même est supprimé. Copier les fichiers ici les déplace dans le répertoire Lingua Forge i18n-overrides, qui persiste à travers tous ces événements et est chargé automatiquement à chaque requête.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copier dans le stockage sécurisé','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacité WordPress la plus basse autorisée pour déclencher les fonctionnalités d\'IA. En restreignant cela sur les sites multi-auteurs, on empêche les contributeurs ou comptes d\'essai d\'exécuter des appels payants à l\'IA. Peut être surchargé par fonctionnalité via le filtre linguaforge_required_capability.','Maintenance'=>'Maintenance','Maintenance Tab'=>'Onglet Maintenance','Make casual'=>'Rendre informel','Make concise'=>'Rendre concis','Make formal'=>'Rendre formel','Mark citations needed'=>'Marquer les citations nécessaires','Max context characters'=>'Caractères max du contexte','Max hints characters'=>'Caractères max pour les indices','Max input characters'=>'Caractères d\'entrée max','Max output tokens'=>'Tokens de sortie max','Maximum characters accepted from the input field. Default: 8 000.'=>'Nombre maximum de caractères acceptés depuis le champ de saisie. Par défaut : 8 000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Nombre maximum de caractères du contenu de message existant transmis à l\'IA comme contexte de départ lorsque aucun indice n\'est fourni. Par défaut : 6 000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Nombre maximum de caractères lus depuis le champ d\'indices. Par défaut : 2 000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Nombre maximum de caractères du contenu du message transmis à l\'IA. 0 signifie aucune limite — le contenu complet est toujours envoyé (recommandé). Définissez une valeur non nulle uniquement si votre fournisseur dispose d\'une fenêtre de contexte limitée. Un avertissement est écrit dans le journal d\'erreurs PHP chaque fois que le contenu est tronqué.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Nombre maximum de tokens que l\'IA peut produire dans une seule réponse de traduction. Si une traduction est coupée silencieusement à la fin, augmentez cette valeur. Par défaut : 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Nombre maximum de jetons que l\'IA peut produire par exécution de génération. Augmentez cette valeur si les articles complets sont coupés. Par défaut : 8 192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Nombre maximum de jetons que l\'IA peut produire par traduction rapide. Par défaut : 2 000.','Meta Description'=>'Meta description','Meta description'=>'Meta description','Meta Description, Excerpt Generator'=>'Description Meta, Générateur d\'extraits','Metric'=>'Métrique','Minimum role'=>'Rôle minimum','Missing pattern name or language.'=>'Nom de motif ou langue manquante.','Mode'=>'Mode','Model'=>'Modèle','Model tier'=>'Niveau du modèle','Models'=>'Modèles','Models Tab (General)'=>'Onglet Modèles (Général)','Modified'=>'Modifié','Most recent cached block'=>'Bloc mis en cache le plus récent','Most recent cached response'=>'Réponse mise en cache la plus récente','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Routing multilingue, balises méta SEO et outils de contenu IA pour WordPress. Combine détection de la langue, routage d\'URL, hreflang, descriptions méta, et fonctionnalités d\'extrait, méta et traduction alimentées par IA.','Name displayed in this language. Leave empty to use the source name.'=>'Nom affiché dans cette langue. Laissez vide pour utiliser le nom source.','Navigation'=>'Navigation','Navigation has no content to translate.'=>'La navigation n\'a pas de contenu à traduire.','Navigation not found.'=>'Navigation non trouvée.','Navigation posts are translated via the Router tab, not this button.'=>'Les publications de navigation sont traduites via l\'onglet Router, pas ce bouton.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traduction de la navigation nécessite un fournisseur AI actif. Configurez une clé API dans l\'onglet Clés API.','Navigations'=>'Navigations','Network error — could not reach the WordPress AJAX endpoint.'=>'Erreur réseau — impossible d\'atteindre le point de terminaison AJAX de WordPress.','No %s version found in this translation group.'=>'Aucune version %s trouvée dans ce groupe de traduction.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Aucune action nécessaire. Google a déprécié son endpoint de ping sitemap en janvier 2024 et découvre désormais les sitemaps exclusivement via la directive Sitemap du robots.txt — que LF a déjà configurée. Google le prendra en compte lors de son prochain crawl.','No AI provider configured.'=>'Fournisseur d\'IA non configuré.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Aucun fournisseur d\'IA configuré. Ajoutez une clé API dans Paramètres → Clés API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Aucune utilisation de l\'IA enregistrée dans la période sélectionnée (%s). Choisissez une plage plus large ci-dessus.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Aucune utilisation de l\'IA enregistrée pour le moment. Une fois qu\'un éditeur effectue une traduction, génère une méta-description ou utilise toute autre fonctionnalité AI, les totaux apparaîtront ici.','No API key configured for this provider.'=>'Aucune clé API configurée pour ce fournisseur.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Aucune instruction intégrée — chaque fonctionnalité IA utilise ses propres paramètres par défaut. Remplissez le champ Instructions de l\'invite personnalisée ci-dessous pour ajouter vos propres règles à l\'échelle du site.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Aucun plugin SEO en conflit détecté. Lingua Forge gère toute la sortie SEO de manière indépendante.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Aucun fichier personnalisé Loco Translate trouvé pour le moment. Ils apparaissent ici une fois que vous enregistrez une traduction dans Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Aucun plugin OG externe détecté. LF produit l\'ensemble complet OG + Twitter Card.','No file was selected.'=>'Aucun fichier n\'a été sélectionné.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Aucune entrée de glossaire ne correspond au filtre actuel. Effacez le filtre pour voir toutes les entrées, ou ajoutez une nouvelle entrée ci-dessous.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Aucune entrée de glossaire pour le moment. Ajoutez-en une ci-dessous pour commencer à appliquer la terminologie dans les traductions.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Aucun H1 trouvé. En général, le titre du post est le H1 — vérifiez que votre thème l\'affiche.','No images found in content.'=>'Aucune image trouvée dans le contenu.','No internal links found to update.'=>'Aucun lien interne trouvé à mettre à jour.','No language-specific template parts found to map.'=>'Aucune partie de modèle spécifique à la langue trouvée à mapper.','No LF meta description set — using excerpt/content.'=>'Aucune meta description LF définie — utilisation d\'un extrait/contenu.','No links found. Internal links improve crawlability and user navigation.'=>'Aucun lien trouvé. Les liens internes améliorent la crawlabilité et la navigation utilisateur.','No meta description found. Generate one via the AI meta description feature.'=>'Aucune meta description trouvée. Générez-en une via la fonction meta description IA.','No navigation references needed updating.'=>'Aucune référence de navigation à mettre à jour.','No override files uploaded yet.'=>'Aucun fichier de surcharge téléchargé pour le moment.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Aucun fichier robots.txt physique trouvé. WordPress le génère virtuellement et la directive Sitemap de LF est incluse automatiquement.','No published posts found for the selected filters.'=>'Aucun article publié trouvé pour les filtres sélectionnés.','No response from AI provider. Check your API key and try again.'=>'Aucune réponse du fournisseur d\'IA. Vérifiez votre clé API et réessayez.','No response from provider — check the error log for details.'=>'Aucune réponse du fournisseur — vérifiez le journal des erreurs pour plus de détails.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Aucune langue secondaire configurée. Installez un pack linguistique ci-dessus pour activer la création de modèles.','No source content found to translate.'=>'Aucun contenu source trouvé à traduire.','No source page linked yet.'=>'Aucune page source liée pour le moment.','No template part references needed updating.'=>'Aucune référence de partie de modèle à mettre à jour.','No title set.'=>'Aucun titre défini.','No translated content found. The sitemap will populate once posts have been translated.'=>'Aucun contenu traduit trouvé. Le sitemap sera rempli une fois que les articles auront été traduits.','No translation found — analyzed the source language version.'=>'Aucune traduction trouvée — version de la langue source analysée.','No {lang} translation registered (TRID missing)'=>'Aucune traduction {lang} enregistrée (TRID manquant)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Pas encore généré. Le sitemap est construit lors de la première visite à l\'URL du sitemap et mis en cache pendant 24 heures.','Notes'=>'Notes','Nothing — all types disabled'=>'Rien — tous les types désactivés','Notice message'=>'Message de notification','Notice settings'=>'Paramètres de notification','Notify search engines'=>'Notifier les moteurs de recherche','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Balises OG/Twitter Card : gérées par le module Open Graph de LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Bloc mis en cache le plus ancien','Oldest cached response'=>'Réponse mise en cache la plus ancienne','Only .mo files are accepted.'=>'Seuls les fichiers .mo sont acceptés.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Cartes Open Graph &amp; Twitter','Open Graph output'=>'Sortie Open Graph','Open Graph settings saved.'=>'Paramètres Open Graph enregistrés.','Open Search Console →'=>'Ouvrir la Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Ouvrir la feuille de partage Web native du navigateur (iOS, Android, certains desktops). Repli sur la copie dans le presse-papiers si non supporté.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contexte optionnel pour les éditeurs (par ex. "ASIC = Circuit intégré spécifique à l\'application ; à conserver en anglais dans les contextes techniques").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Optionnel. Bing lit déjà la directive Sitemap: depuis robots.txt — cela déclenche une recrawl immédiate au lieu d\'attendre la prochaine vérification programmée.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Optionnel. Yandex lit déjà la directive Sitemap: depuis robots.txt — cela déclenche une recrawl immédiate au lieu d\'attendre la prochaine vérification programmée.','Output'=>'Sortie','Output Article or WebPage schema on singular posts and pages'=>'Sortie du schéma Article ou WebPage sur les articles et pages singuliers','Output hreflang tags in wp_head'=>'Sortie des balises hreflang dans wp_head','Output mode'=>'Mode de sortie','Output Open Graph tags in wp_head'=>'Sortie des balises Open Graph dans wp_head','Output Product schema on WooCommerce product pages'=>'Sortie du schéma Product sur les pages produits WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Sortie du JSON-LD Schema.org dans wp_head','Output tokens'=>'Tokens de sortie','Output WebSite schema on the front page and blog index'=>'Sortie du schéma WebSite sur la page d\'accueil et l\'index du blog','Overall SEO score'=>'Score SEO global','overridden'=>'surchargé','Override file deleted.'=>'Fichier de remplacement supprimé.','Override file uploaded successfully.'=>'Fichier de remplacement téléchargé avec succès.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Remplace le préréglage AI pour la traduction et la génération de contenu sur cette page. Toutes les autres fonctionnalités utilisent toujours le préréglage global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Remplace le préréglage AI pour la traduction et la génération de contenu sur cette page. Les instructions de prompt personnalisées à l\'échelle du site (Paramètres → Comportement) sont toujours ajoutées à chaque requête, indépendamment de cette sélection.','Overview'=>'Aperçu','Page'=>'Page','Part'=>'Partie','Paste a footnote, sentence, or any snippet here…'=>'Collez une note de bas de page, une phrase ou un extrait ici…','Paste text, or select text in the editor first…'=>'Collez du texte, ou sélectionnez d\'abord du texte dans l\'éditeur…','Paste text, or select text on the page first…'=>'Collez du texte, ou sélectionnez d\'abord du texte sur la page…','Paste your API key…'=>'Collez votre clé API…','Path prefix — example.com/de/'=>'Préfixe de chemin — example.com/fr/','Pattern'=>'Modèle','Pattern has no content to translate.'=>'Le motif n\'a pas de contenu à traduire.','Pattern not found.'=>'Motif non trouvé.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Motif traduit et enregistré. Copiez le contenu dans votre publication CPT via l\'inserteur de motifs de l\'éditeur de blocs ou utilisez-le comme point de départ pour un bloc réutilisable.','Pattern translation failed.'=>'Échec de la traduction du modèle.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Cache par article pour les traductions générées par IA, les descriptions méta, les extraits et le contenu. Toujours actif — aucune bascule séparée requise. Les entrées sont invalidées automatiquement lorsque le contenu ou le fournisseur/modèle d\'IA change.','Permalink rules flushed successfully.'=>'Les règles de permaliens ont été vidées avec succès.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Supprime définitivement tous les modèles, parties de modèles, motifs, menus de navigation, articles, pages, types de publication personnalisés, produits et variations de produits associés à cette langue. Supprime également les fichiers du pack de localisation WordPress afin que cette langue n\'apparaisse plus dans le routeur. Cette action est irréversible.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Désinstaller définitivement %s ? Cela supprimera tout le contenu traduit pour cette langue et ne pourra pas être annulé.','Permission denied.'=>'Permission refusée.','Persuasive'=>'Persuasive','PHP constant'=>'constante PHP','Pin on Pinterest'=>'Épingler sur Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Épingler les termes qui ne doivent pas être traduits ou qui doivent toujours être rendus d\'une manière spécifique (par exemple, noms de marques, noms de produits, acronymes). Les contraintes du glossaire sont injectées dans chaque requête de traduction AI pour toutes les fonctionnalités : traduction de post, description meta, extrait et traduction de modèle FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Langage simple','Please enter some instructions first…'=>'Veuillez d\'abord entrer des instructions…','Please enter some text first…'=>'Veuillez d\'abord entrer du texte…','Plugin'=>'Plugin','Post'=>'Article','Post not found or not published.'=>'Article non trouvé ou non publié.','Post not found.'=>'Article non trouvé.','Post on X / Twitter'=>'Article sur X / Twitter','Post Types'=>'Types de publication','Prefilled from excerpt. Edit to override.'=>'Rempli à partir de l\'extrait. Modifier pour écraser.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Le prix et la disponibilité reflètent toujours le produit dans la langue source (modèle de stock partagé). Les balises ne sont affichées que lorsque le module Open Graph de LF est réglé sur "Complet" ou "Auto" sans plugin SEO en conflit détecté.','Primary Language'=>'Langue principale','Primary language'=>'Langue principale','Primary language saved.'=>'Langue principale enregistrée.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Langue principale : la langue dans laquelle votre contenu existant est écrit. Toutes les traductions sont produites à partir de cette langue ; la changer ne déplace ni ne supprime aucun article.','Processing…'=>'Traitement…','Product'=>'Produit','Product Open Graph'=>'Open Graph du produit','Product — WooCommerce product pages'=>'Produit — pages de produits WooCommerce','Provider'=>'Fournisseur','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Le fournisseur n\'a renvoyé aucun texte. Vérifiez le journal des erreurs de WordPress pour connaître la raison détaillée de l\'échec.','Quality'=>'Qualité','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualité (par défaut — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualité (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualité : utilisée pour la traduction de posts et la génération de contenu — qualité supérieure, coût plus élevé.','Quick Translate'=>'Traduction rapide','Quick Translation'=>'Traduction rapide','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traduction rapide est utilisée en mode extrait / fragment — passages courts traduits à la demande depuis la barre d\'outils, l\'éditeur ou les infobulles de bloc. Elle utilise une configuration séparée, plus légère, de la traduction en page complète pour garder les réponses rapides et économiques.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Réactive la fonction canLockBlocks de Gutenberg. Utile pour les modèles éditoriaux qui doivent empêcher les contributeurs de déplacer ou supprimer des blocs spécifiques.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Réactive supportsTemplateMode. Essentiel pour les flux de travail de l\'édition complète du site où les overrides de modèle au niveau de la publication sont intentionnels.','Re-generates and updates the cached result.'=>'Re-génère et met à jour le résultat en cache.','Re-scan'=>'Rescanner','Re-scanning…'=>'Ré-analyse…','Re-translate'=>'Re-traduire','Reading time'=>'Temps de lecture','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirigez les visiteurs vers leur langue préférée en fonction de l\'en-tête Accept-Language du navigateur','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Affiner davantage — par exemple "raccourcir" ou "utiliser un ton formel"…','Refine further:'=>'Affiner davantage :','Refinement'=>'Affinement','Refinement failed — please try again.'=>'L\'affinement a échoué — veuillez réessayer.','Refining…'=>'En cours d\'affinement…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Régénère les règles de réécriture de WordPress pour que les préfixes d\'URL, les slugs spécifiques à la langue et les réécritures d\'archives soient tous synchronisés. Nécessaire après avoir changé la langue principale ou ajouté un nouveau support linguistique.','Remove stored key'=>'Supprimer la clé stockée','Report an issue on GitHub'=>'Signaler un problème sur GitHub','Request failed — please try again.'=>'La requête a échoué — veuillez réessayer.','Request failed.'=>'La requête a échoué.','Request failed. Check your connection.'=>'Échec de la requête. Vérifiez votre connexion.','Request failed. Please try again.'=>'Échec de la requête. Veuillez réessayer.','Requests'=>'Requêtes','Reset'=>'Réinitialiser','Result will appear here…'=>'Le résultat apparaîtra ici…','Retranslate'=>'Retraduire','Retranslating…'=>'Retraduction en cours…','Review carefully — links and slugs not updated.'=>'Vérifiez attentivement — liens et slugs non mis à jour.','Review translation before applying'=>'Réviser la traduction avant d\'appliquer','Revise'=>'Réviser','Revision'=>'Révision','Revision Type'=>'Type de révision','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt mis à jour avec directive Sitemap.','Router'=>'Routeur','Router Tab'=>'Onglet Routeur','Run AI Analysis'=>'Lancer l\'analyse IA','Save Debug Setting'=>'Enregistrer le paramètre de débogage','Save Hreflang Settings'=>'Enregistrer les paramètres Hreflang','Save Open Graph Settings'=>'Enregistrer les paramètres Open Graph','Save Router Settings'=>'Enregistrer les paramètres du routeur','Save Schema.org Settings'=>'Enregistrer les paramètres Schema.org','Save Settings'=>'Enregistrer les paramètres','Save Sitemap Settings'=>'Enregistrer les paramètres Sitemap','Save Social Share Settings'=>'Enregistrer les paramètres de partage social','Save the post to persist changes.'=>'Enregistrer le message pour sauvegarder les modifications.','Save Uninstall Setting'=>'Enregistrer le paramètre de désinstallation','Save WooCommerce SEO Settings'=>'Enregistrer les paramètres SEO WooCommerce','Saved to the meta description field when you apply.'=>'Enregistré dans le champ de meta description lors de l\'application.','Scan failed: '=>'Échec de l\'analyse :','Scan request failed. Please try again.'=>'Échec de la demande d\'analyse. Veuillez réessayer.','Scanning posts for broken language links…'=>'Analyse des publications pour liens linguistiques cassés…','Schema output deferred.'=>'Sortie du schéma différée.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD Schema.org','Schema.org output'=>'Sortie Schema.org','Schema.org settings saved.'=>'Paramètres Schema.org enregistrés.','Search'=>'Recherche','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console est utile pour surveiller les erreurs d\'indexation et de couverture, mais n\'est pas nécessaire pour la découverte.','Search Results'=>'Résultats de recherche','Security check failed — file path is not permitted.'=>'Échec de la vérification de sécurité — le chemin du fichier n\'est pas autorisé.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Sélectionnez une langue pour gérer ses modèles FSE, ses parties de modèles et ses menus de navigation.','Select language'=>'Sélectionner la langue','Send via Telegram'=>'Envoyer via Telegram','Send via WhatsApp'=>'Envoyer via WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Analyse SEO','SEO character-count info'=>'Infos sur le nombre de caractères SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Plugins SEO détectés : %s. LF ne sort que og:locale et og:locale:alternate ; le plugin détecté gère l\'ensemble complet OG.','SEO plugins and conflict avoidance:'=>'Plugins SEO et évitement des conflits :','SEO Tab'=>'Onglet SEO','Server setup (subdomain)'=>'Configuration du serveur (sous-domaine)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Définit le comportement par défaut de l\'IA pour toutes les fonctionnalités du site. Les publications individuelles peuvent le remplacer pour la traduction et la génération de contenu via la boîte méta Lingua Forge.','Settings'=>'Paramètres','Settings saved.'=>'Paramètres enregistrés.','Share on Facebook'=>'Partager sur Facebook','Share on LinkedIn'=>'Partager sur LinkedIn','Share on Mastodon'=>'Partager sur Mastodon','Share via email (mailto:)'=>'Partager par email (mailto:)','Show home link'=>'Afficher le lien vers la page d\'accueil','Shown when no translation exists for the visitor\'s language.'=>'Affiché lorsqu\'aucune traduction n\'existe dans la langue du visiteur.','Single'=>'Unique','Single %s'=>'Unique %s','Single: %s'=>'Unique : %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Plafond global du site sur les requêtes d\'IA par jour UTC (compte à la fois les traductions de la barre d\'outils et les révisions de blocs). Le compteur se réinitialise à minuit UTC. Mettre à 0 pour désactiver le plafond.','Sitemap'=>'Sitemap','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Cache du sitemap vidé. Il sera régénéré lors de la prochaine visite à l\'URL du sitemap.','Sitemap output'=>'Sortie du sitemap','Sitemap settings saved.'=>'Paramètres du sitemap enregistrés.','Sitemap URL'=>'URL du sitemap','Size'=>'Taille','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Partage du bloc d\'icônes sociales : URLs : géré par le partage social intégré de LF (SEO → Partage social)','Social Share'=>'Partage social','Social Share settings saved.'=>'Paramètres de partage social enregistrés.','Some link fixes failed.'=>'Certaines corrections de liens ont échoué.','Some nav ref fixes failed.'=>'Certaines corrections de références de navigation ont échoué.','Some part fixes failed.'=>'Certaines corrections de parties ont échoué.','Some parts could not be created.'=>'Certaines parties n\'ont pas pu être créées.','Some templates could not be created.'=>'Certains modèles n\'ont pas pu être créés.','Some translations failed.'=>'Certaines traductions ont échoué.','source'=>'source','Source file not found.'=>'Fichier source non trouvé.','Source lang'=>'Langue source','Source language'=>'Langue source','Source term'=>'Terme source','Standard'=>'Standard','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard utilise la température réglée pour chaque fonctionnalité : Traduction T=0.2 (précis), Traduction rapide T=0.4, Générateur de contenu T=0.6 (créatif). Les autres préréglages appliquent une température fixe unique à toutes les fonctionnalités.','Status'=>'Statut','Status / Actions'=>'Statut / Actions','Storytelling'=>'Narration','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode de préservation stricte pour le contenu juridique, réglementaire, médical ou technique. Lorsqu\'il est activé, chaque fonctionnalité IA utilise une température d\'échantillonnage faible et ajoute l\'addendum ci-dessous à son invite système — la terminologie, les numéros d\'article, les unités, les noms de marque et le langage réglementaire sont conservés mot à mot plutôt que paraphrasés.','Structured Outline'=>'Plan structuré','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Le mode sous-domaine nécessite que votre serveur web pointe tous les sous-domaines de langue (par exemple, fr.exemple.com) vers cette installation WordPress. Après avoir changé de mode, videz les règles de permalien et effacez tous les caches. Si votre URL d\'accueil inclut www (par exemple, www.exemple.com), utilisez le filtre lf_base_domain pour définir le domaine racine nu afin que les sous-domaines soient construits correctement.','Subdomain — de.example.com/'=>'Sous-domaine — fr.exemple.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Soumettez cette URL à Google Search Console avec votre sitemap principal.','Submit to Reddit'=>'Soumettre à Reddit','Suggested meta description'=>'Meta description suggérée','Suggested title'=>'Titre suggéré','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Fournisseurs pris en charge : Anthropic (Claude), OpenAI (GPT), Google (Gemini). Un seul fournisseur est actif à la fois. Sélectionnez le fournisseur actif dans l\'onglet Général.','Suppressed: %s.'=>'Supprimé : %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, par fonctionnalité','Tag'=>'Étiquette','Tags emitted'=>'Étiquettes émises','Target lang'=>'Langue cible','Target Language'=>'Langue cible','Target language'=>'Langue cible','Target term'=>'Terme cible','Target: 140–160 chars for optimal SERP display'=>'Cible : 140–160 caractères pour un affichage optimal dans les SERP','Technical'=>'Technique','Technical / Scientific'=>'Technique / Scientifique','Technical / Scientific instructions'=>'Instructions techniques / scientifiques','Template "%s" already exists.'=>'Modèle "%s" existe déjà.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Le modèle "{expected}" n\'existe pas — créez-le d\'abord dans l\'éditeur de site.','Template has no content.'=>'Le modèle n\'a pas de contenu.','Template mode'=>'Mode modèle','Template not found or not stored in the database.'=>'Modèle non trouvé ou non stocké dans la base de données.','Template part "%s" already exists.'=>'Partie de modèle "%s" existe déjà.','Template part has no content.'=>'La partie de modèle n\'a pas de contenu.','Template part not found or not stored in the database.'=>'Partie de modèle non trouvée ou non stockée dans la base de données.','Template Parts'=>'Parties de modèles','Templates'=>'Modèles','Test connection'=>'Tester la connexion','Testing…'=>'Test en cours…','Text domain / locale'=>'Domaine de texte / locale','Text to translate'=>'Texte à traduire','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Le cache de réponse API stocke le résultat brut de chaque requête AI — traduction, description meta, extrait et génération de contenu — indexé par une empreinte des entrées (contenu, paire de langues, fournisseur, modèle). Les requêtes ultérieures avec des entrées identiques sont servies depuis le cache sans appel API. Le cache est différent de la Mémoire de traduction : la Mémoire de traduction fonctionne au niveau du bloc et est partagée entre les articles ; le cache de réponse API fonctionne au niveau de la fonctionnalité et est indexé par article.','The editor did not accept the content — please try again.'=>'L\'éditeur n\'a pas accepté le contenu — veuillez réessayer.','The following directive is active in your virtual robots.txt:'=>'La directive suivante est active dans votre robots.txt virtuel :','The lf-social-share mu-plugin is active.'=>'Le plugin mu lf-social-share est actif.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Le plugin mu lf-social-share est actif. La fonction intégrée de partage social de Lingua Forge est inactive — le plugin mu gère la réécriture des URL de partage et les actions JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Le niveau Léger utilise le modèle rapide configuré dans la table des modèles ci-dessus (par défaut : Haiku / Flash). Passez à la Qualité si vous avez besoin de la même précision de traduction que le mode en page complète pour les extraits.','The phrase as it appears in the source text.'=>'L\'expression telle qu\'elle apparaît dans le texte source.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'La langue principale est toujours servie à la racine de votre site — pas de préfixe URL en mode chemin, pas de sous-domaine de langue en mode sous-domaine. Toutes les autres langues utilisent soit un préfixe de chemin /lang/ (ex. example.com/de/) soit un sous-domaine de langue (ex. de.example.com), selon la configuration de l\'URL ci-dessous.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'L\'onglet SEO → Compatibilité affiche le statut de détection en direct et explique précisément ce que LF fait pour chaque domaine de fonctionnalité.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'L\'URL de partage reflète toujours la page en cours — aucune saisie manuelle d\'URL n\'est nécessaire. Le filtre linguaforge_social_share_url vous permet de remplacer l\'URL résolue pour tout service.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Le sitemap est annoncé automatiquement dans robots.txt. Tous les principaux moteurs de recherche — Google, Bing, Yandex — le découvrent via robots.txt. Aucune soumission manuelle n\'est requise.','The source page has no footnotes.'=>'La page source n\'a pas de notes de bas de page.','The upload failed — please try again.'=>'Le téléchargement a échoué — veuillez réessayer.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Le sitemap du cœur WordPress liste toutes vos URLs de contenu. Le sitemap LF indique aux moteurs de recherche comment les versions linguistiques sont reliées via des alternances xhtml:link hreflang. Soumettez les deux à Google Search Console pour une couverture complète.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Ces notes de bas de page proviennent de la page source et sont affichées ici à titre de référence uniquement. Ajoutez-les à cette page en utilisant l\'éditeur de blocs.','This is the source page. Footnotes are edited directly in the block editor.'=>'Ceci est la page source. Les notes de bas de page sont modifiées directement dans l\'éditeur de blocs.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Cette clé est actuellement fournie par un serveur %s et ne peut pas être supprimée ici. Entrez une nouvelle clé ci-dessus pour la remplacer par une valeur de la base de données.','This language is protected and cannot be uninstalled.'=>'Cette langue est protégée et ne peut pas être désinstallée.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Cette langue correspond à la locale de l\'instance WordPress et ne peut pas être désinstallée.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Astuce : pour réinitialiser un modèle à la valeur par défaut intégrée, effacez le champ et enregistrez.','Title'=>'Titre','Title is %d chars — aim for 50–60.'=>'Le titre fait %d caractères — visez 50–60.','Title is %d chars — may be truncated in SERPs (aim for 50–60).'=>'Le titre fait %d caractères — peut être tronqué dans les SERPs (visez 50–60).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Pour utiliser un secret de chiffrement personnalisé (au lieu de la valeur dérivée wp_salt), ajoutez ceci dans wp-config.php :','Today'=>'Aujourd\'hui','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'La consommation de tokens est regroupée par fonctionnalité, fournisseur et modèle. Enregistrée à chaque appel AI réussi ; les pings de test de connexion sont exclus pour ne pas fausser les totaux.','Tone'=>'Ton','tone'=>'ton','Tone:'=>'Ton :','Too many AI requests. Please retry in %d seconds.'=>'Trop de demandes d\'IA. Veuillez réessayer dans %d secondes.','Total'=>'Total','Total tokens'=>'Tokens totaux','Translate'=>'Traduire','Translate / Revise'=>'Traduire / Réviser','Translate / Revise block'=>'Traduire / Réviser le bloc','Translate all'=>'Tout traduire','Translate chunk'=>'Traduire le segment','Translate Content'=>'Traduire le contenu','Translate missing'=>'Traduction manquante','Translate page…'=>'Traduire la page…','Translated content'=>'Contenu traduit','Translated Names'=>'Noms traduits','Translated title'=>'Titre traduit','Translated to:'=>'Traduit en :','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traduit. Vérifiez dans l\'éditeur de site — les liens internes, URL de navigation et slugs de modèles ne sont pas mis à jour automatiquement.','Translating…'=>'Traduction en cours…','Translation'=>'Traduction','Translation Caching'=>'Mise en cache de la traduction','Translation found but permalink could not be generated'=>'Traduction trouvée mais le permalien n\'a pas pu être généré','Translation Limits'=>'Limites de traduction','Translation Limits & Behavior'=>'Limites et comportement de la traduction','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Limites de traduction : contrôlez quels rôles d\'utilisateur peuvent déclencher la traduction par IA, et définissez un budget mensuel de jetons. Dépasser le budget suspend les appels à l\'IA jusqu\'à la réinitialisation du mois.','Translation Memory'=>'Mémoire de traduction','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'La mémoire de traduction met en cache les résultats de l\'IA par empreinte du contenu, paire de langues, fournisseur et modèle. Modifier un message invalide l\'entrée du cache afin que le prochain appel de traduction obtienne un résultat frais.','Translation Memory cleared. %d cached block was removed.'=>'Mémoire de traduction vidée. %d bloc mis en cache a été supprimé.' . "\0" . 'Mémoire de traduction vidée. %d blocs mis en cache ont été supprimés.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Mémoire de traduction : stocke le message traduit complet par empreinte du contenu. Effacez-la lorsque vous souhaitez forcer une retraduction de tous les messages, indépendamment de leur contenu.','Translation workflow'=>'Flux de travail de traduction','Translation, Content Generator'=>'Traduction, Générateur de contenu','Type'=>'Type','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Désinstaller %s','Uninstall Behaviour'=>'Désinstaller le comportement','Uninstall setting saved.'=>'Paramètre de désinstallation enregistré.','unknown error'=>'erreur inconnue','Unknown provider.'=>'Fournisseur inconnu.','Unknown search engine.'=>'Moteur de recherche inconnu.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Contrairement à hreflang — où LF écrase toujours les autres plugins car ils ne peuvent pas connaître votre configuration multilingue — Open Graph est différent : Yoast, Rank Math et plugins similaires produisent déjà des balises OG correctes pour votre contenu. Les dupliquer n\'apporte aucune valeur. En mode automatique, LF détecte les plugins SEO actifs et ajoute uniquement ce qu\'ils ne peuvent pas fournir : og:locale (langue actuelle) et og:locale:alternate (toutes les autres langues configurées).','Up'=>'Haut','Upload .mo file'=>'Télécharger le fichier .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Téléchargez les fichiers .mo compilés pour remplacer les chaînes du plugin tiers pour des locales spécifiques — par exemple, une traduction personnalisée de VikBooking qui utilise "appartement" au lieu de "chambre". Les fichiers doivent suivre la convention de nommage de WordPress : {textdomain}-{locale}.mo (ex. vikbooking-ca.mo). Ils sont stockés dans le dossier uploads et survivent aux mises à jour du plugin.','Upload Override'=>'Télécharger la surcharge','URL could not be mapped to a post — check the link target exists'=>'L\'URL n\'a pas pu être associée à un article — vérifiez que la cible du lien existe','URL structure'=>'Structure URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Structure d\'URL : mode préfixe de chemin (exemple.com/de/) ne nécessite pas de modifications du serveur. Mode sous-domaine (de.exemple.com) nécessite un enregistrement DNS générique, un certificat SSL générique, et une modification de la configuration du serveur web — voir le guide de configuration du serveur.','URL to enter'=>'URL à saisir','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Utiliser le partage natif si disponible ; sinon, copier dans le presse-papiers. Recommandé par défaut pour les boutons "Partager".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Utilisez les onglets en haut de cette page pour configurer chaque zone. Les modifications de l\'onglet Routeur prennent effet immédiatement ; celles des clés AI et des paramètres du modèle s\'appliquent à la prochaine requête AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Table de terminologie gérée par l\'utilisateur par paire de langues. Les entrées sont ajoutées à l\'invite du système de traduction afin que l\'IA utilise de manière cohérente les termes préférés — essentiel pour le vocabulaire spécifique au domaine ("kWp", "PPA", "point d\'interconnexion"), les noms de marques qui ne doivent pas être traduits, et la formulation réglementaire standardisée. Les deux champs de langue sont facultatifs : laissez "Langue source" vide pour appliquer l\'entrée indépendamment de la langue de traduction ; laissez "Langue cible" vide pour l\'appliquer à toutes les langues cibles en même temps.','Using custom meta description.'=>'Utilisation d\'une meta description personnalisée.','Using LF AI meta description.'=>'Utilisation de la méta description AI de LF.','Value source'=>'Source de la valeur','View'=>'Voir','View built-in default'=>'Voir la valeur par défaut intégrée','View current robots.txt'=>'Voir le robots.txt actuel','View details'=>'Voir les détails','View Lingua Forge details'=>'Voir les détails de Lingua Forge','Visit plugin site'=>'Visiter le site du plugin','Warning:'=>'Avertissement :','WebSite'=>'Site Web','WebSite — front page / blog index'=>'Site Web — page d\'accueil / index du blog','What LF provides — and collision avoidance'=>'Ce que LF fournit — et évitement des collisions','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Ce que LF fournit : balises hreflang pour chaque langue configurée, balises Open Graph et Twitter Card avec og:locale et og:locale:alternate, JSON-LD Schema.org avec annotations inLanguage, et un sitemap multilingue dédié à /lf-sitemap.xml avec des entrées xhtml:link alternate pour tous les groupes de traduction.','When another SEO plugin is installed'=>'Lorsqu\'un autre plugin SEO est installé','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Lorsque la journalisation de débogage est activée (via le bouton ci-dessous ou en définissant LINGUAFORGE_AI_DEBUG dans wp-config.php), les fonctionnalités de traduction et de traduction de modèles FSE écrivent leurs invites AI brutes et leurs réponses sur le disque pour le dépannage. Utilisez cette section pour surveiller cette sortie et la supprimer une fois que vous avez ce dont vous avez besoin — les fichiers peuvent rapidement devenir volumineux sur de grandes pages. Configurez le répertoire de destination via le filtre linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Lorsqu\'il est activé, les visiteurs pour la première fois sans cookie de langue et sans préfixe de langue dans l\'URL sont redirigés vers la version linguistique la plus proche. La redirection est ignorée si la langue préférée du navigateur ne fait pas partie des langues actives du routeur. Une fois qu\'un visiteur choisit une langue via le sélecteur, le cookie prime et l\'en-tête du navigateur est ignoré lors de toutes les visites futures.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Lorsqu\'il est activé, Lingua Forge émet les balises meta supplémentaires suivantes sur les pages produits : og:type=product, og:price:amount, og:price:currency, og:availability, et leurs équivalents dans l\'espace de noms product : utilisés par Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Lorsqu\'il est activé, l\'URL du sitemap est annoncée automatiquement dans robots.txt et le cache est rafraîchi lorsque le contenu traduit est enregistré.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Lorsqu\'Yoast SEO, Rank Math, All in One SEO ou SEOPress est actif, Lingua Forge supprime automatiquement leur sortie hreflang via un filtre. Les plugins SEO généraux produisent hreflang basé sur une structure d\'URL monolingue et ne peuvent pas prendre en compte votre configuration de routage multilingue ; la sortie de LF est toujours correcte.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Quel niveau de modèle utiliser pour la traduction de page complète. La qualité utilise le modèle configuré dans la table Modèles ci-dessus et est recommandée pour une traduction précise et longue. Passez à Léger uniquement si la vitesse ou le coût sont prioritaires et si le contenu est court.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Pendant son activation, le plugin mu gère l\'ensemble de l\'ensemble OG de base et LF n\'émet que des balises de locale (mode automatique). La suppression de celui-ci passe LF en mode OG complet automatiquement.','WooCommerce'=>'WooCommerce','WooCommerce product price'=>'Prix du produit WooCommerce','WooCommerce SEO settings saved.'=>'Paramètres SEO WooCommerce enregistrés.','WooCommerce store currency'=>'Devise du magasin WooCommerce','Word count'=>'Nombre de mots','WP core canonical active (hreflang disabled)'=>'Canonical WP actif (hreflang désactivé)','WP-CLI reference'=>'Référence WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Écrire les invites AI et les réponses sur le disque pour le dépannage','XML Sitemap'=>'Sitemap XML','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Vous pouvez également définir des clés comme constantes ou variables d\'environnement (par exemple dans wp-config.php). Ces sources sont utilisées automatiquement comme solution de secours lorsqu\'aucune clé de base de données n\'est stockée.','You do not have permission to manage these settings.'=>'Vous n\'avez pas la permission de gérer ces paramètres.','You do not have permission to read this post.'=>'Vous n\'avez pas la permission de lire cet article.','{n} stale path(s)'=>'{n} chemin(s) obsolète(s)','~%d min read'=>'~%d min de lecture' . "\0" . '~%d min de lecture','— Any source language —'=>'— Toute langue source —','— Any target language —'=>'— Toute langue cible —','— Any target —'=>'— Toute cible —','— Any —'=>'— Toute —','— auto-detect —'=>'— détection automatique —','— Deferred to plugin'=>'— Reporté au plugin','— Disabled'=>'— Désactivé','— Not detected'=>'— Non détecté','— select a language —'=>'— sélectionner une langue —','— toggle in Settings → Behavior.'=>'— bascule dans Paramètres → Comportement.','← Back'=>'← Retour','↑ Detected from current post'=>'↑ Détecté à partir du message actuel','→ Locale tags only (manual setting)'=>'→ Balises de localisation uniquement (paramètre manuel)','→ Locale tags only — deferring base OG to plugin'=>'→ Balises de localisation uniquement — report du OG de base au plugin','↺ Re-translate'=>'↺ Retraduire','↺ Refine'=>'↺ Affiner','↺ Refresh'=>'↺ Actualiser','↺ Refreshing…'=>'↺ Actualisation…','⚠ Borderline'=>'⚠ Limite','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Aucun article <strong>{lang}</strong> trouvé. Assurez-vous que tous les articles traduits ont leur méta Langue définie sur <strong>{lang}</strong> dans la boîte à outils de langue.','⚠ No changes'=>'⚠ Aucun changement','⚠ No changes — re-scan?'=>'⚠ Aucun changement — re-analyse ?','✅ Fixed ({n})'=>'✅ Corrigé ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Aucun lien cassé ni incohérence de modèle trouvés pour <strong>{lang}</strong>. Analyse de <strong>{scanned}</strong> article(s) et page(s) — toutes les vérifications ont réussi. Les liens des parties du modèle (en-tête, pied de page, barre latérale) ne sont pas inclus ici — utilisez le bouton Corriger les parties du modèle pour vérifier celles-ci séparément.','✅ Template fixed'=>'✅ Modèle corrigé','✓ %s notified successfully.'=>'✓ %s notifié avec succès.','✓ Active'=>'✓ Actif','✓ Active at /lf-sitemap.xml'=>'✓ Actif à /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Actif — %d entrée URL avec des alternances de langue' . "\0" . '✓ Actif — %d entrées URL avec des alternances de langue','✓ Active — full OG + Twitter Cards'=>'✓ Actif — OG complet + Twitter Cards','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Actif — balises de localisation uniquement (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Toutes les parties créées.','✓ All templates created.'=>'✓ Tous les modèles créés.','✓ All translated.'=>'✓ Toutes traduites.','✓ Configured'=>'✓ Configuré','✓ Connection OK'=>'✓ Connexion OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Contenu généré — consultez la superposition pour revoir, affiner et appliquer.','✓ Done'=>'✓ Terminé','✓ Enabled'=>'✓ Activé','✓ Good length'=>'✓ Bonne longueur','✓ Hreflang active'=>'✓ Hreflang actif','✓ In safe storage'=>'✓ En stockage sécurisé','✓ Language installed.'=>'✓ Langue installée.','✓ LF outputs'=>'✓ Sorties LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Sorties LF Article / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ Sorties LF OG complet + Twitter Cards','✓ LF outputs — plugin hreflang suppressed'=>'✓ Sorties LF — hreflang du plugin supprimé','✓ Links fixed.'=>'✓ Liens corrigés.','✓ Nav refs fixed.'=>'✓ Références de navigation corrigées.','✓ Parts fixed.'=>'✓ Parties corrigées.','✓ Pattern translated.'=>'✓ Modèle traduit.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ robots.txt physique trouvé. La directive Sitemap de LF est présente.','✓ Refined — review the updated draft above.'=>'✓ Affiné — veuillez examiner le brouillon mis à jour ci-dessus.','✓ Translation saved'=>'✓ Traduction enregistrée','✓ WP core canonical removed'=>'✓ Canonical de WP core supprimé','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ Échec du ping de %s. L\'URL du sitemap est toujours annoncée dans robots.txt — le moteur de recherche la découvrira lors de son prochain crawl.','✗ Disabled'=>'✗ Désactivé','✗ Error:'=>'✗ Erreur :','✗ Failed:'=>'✗ Échec :','✗ Not configured'=>'✗ Non configuré','✗ Too long'=>'✗ Trop long','✗ Too short'=>'✗ Trop court','❌ Failed'=>'❌ Échec','📄 Wrong template'=>'📄 Mauvais modèle','📍 Stale path (page moved)'=>'📍 Chemin obsolète (page déplacée)']];
